import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const entries = [
  { id: 'rhythm', file: 'js/rhythm.js' },
  { id: 'audio', file: 'js/audio.js' },
  { id: 'app', file: 'js/app.js' },
];
const knownImports = new Map(entries.map(({ id, file }) => [`./${file.split('/').at(-1)}`, id]));
const parts = [
  '// Generated by npm run build. Edit js/rhythm.js, js/audio.js or js/app.js.',
  '// A classic script also works when index.html is opened directly via file://.',
  '(function () {',
  "  'use strict';",
  '  const modules = Object.create(null);',
];

for (const { id, file } of entries) {
  const source = (await readFile(new URL(file, root), 'utf8')).replace(/\r\n/g, '\n');
  const exports = [...source.matchAll(/^export (?:const|function|class) (\w+)/gm)].map((match) => match[1]);
  const transformed = source
    .replace(/^import\s*\{([^}]+)\}\s*from\s*['"]([^'"]+)['"];\s*$/gm, (_, bindings, path) => {
      const dependency = knownImports.get(path);
      if (!dependency) throw new Error(`Unsupported browser dependency in ${file}: ${path}`);
      const names = bindings.trim();
      if (!/^[\w\s,]+$/.test(names)) throw new Error(`Unsupported import bindings in ${file}.`);
      return `const { ${names} } = modules.${dependency};`;
    })
    .replace(/^export (?=(?:const|function|class)\s)/gm, '');
  if (/^\s*(?:import|export)\s/m.test(transformed)) throw new Error(`Unsupported module syntax in ${file}.`);
  parts.push(`\n  // ${file}`, `  modules.${id} = (function () {`, transformed,
    `\n    return { ${exports.join(', ')} };`, '  })();');
}
parts.push('})();', '');
const bundle = parts.join('\n');
const target = new URL('js/metronome.js', root);

if (process.argv.includes('--check')) {
  let existing = '';
  try { existing = (await readFile(target, 'utf8')).replace(/\r\n/g, '\n'); } catch { /* Report the build command below. */ }
  if (existing !== bundle) {
    console.error('Browser bundle is missing or outdated. Run npm run build in pages/metronome.');
    process.exitCode = 1;
  }
} else {
  await writeFile(target, bundle, 'utf8');
  console.log('Built js/metronome.js (classic browser script).');
}
